def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    # Sort and remove duplicates
    sorted_nums = sorted(set(nums))

    # Group into runs of consecutive integers
    groups: list[list[int]] = []
    current: list[int] = [sorted_nums[0]]

    for n in sorted_nums[1:]:
        if n == current[-1] + 1:
            current.append(n)
        else:
            groups.append(current)
            current = [n]
    groups.append(current)

    # Build the result string
    parts: list[str] = []
    for g in groups:
        if len(g) >= 3:
            parts.append(f"{g[0]}..{g[-1]}")
        else:
            parts.append(",".join(str(x) for x in g))

    return ",".join(parts)
